package com.match.course.service;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.match.course.persistence.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.UUID;
@Service public class CourseTrainingReportService { private final CourseTrainingReportMapper mapper; private final CourseMapper courses; public CourseTrainingReportService(CourseTrainingReportMapper mapper,CourseMapper courses){this.mapper=mapper;this.courses=courses;} public CourseTrainingReportRecord get(Integer userId,String courseId){if(courses.selectById(courseId)==null)throw new IllegalArgumentException("课程不存在");return mapper.selectUserCourse(userId,courseId);} @Transactional public CourseTrainingReportRecord save(Integer userId,String courseId,String content){if(courses.selectById(courseId)==null)throw new IllegalArgumentException("课程不存在");CourseTrainingReportRecord r=mapper.selectUserCourse(userId,courseId);if(r==null){r=new CourseTrainingReportRecord();r.setReportId(UUID.randomUUID().toString());r.setUserId(userId);r.setCourseId(courseId);}r.setContent(content==null?"":content);r.setUpdatedAt(LocalDateTime.now());if(r.getReportId()!=null&&mapper.selectById(r.getReportId())==null)mapper.insert(r);else mapper.updateById(r);return r;} }
